        \vspace{-4mm}
        \begin{cvitems} % Description(s) of tasks/responsibilities
            \item {Frontend Development - Advanced to Senior Frontend Developer and technical leader, spearheading architectural decisions and delivering scalable, high-performance frontend solutions.}
        \end{cvitems}
        \begin{cvsubitems}
            \item {Design System \& Component Libraries - Architected and implemented comprehensive frontend design systems and component libraries, ensuring consistency, accessibility, and scalability across the entire codebase.}
            \item {Legacy Migration Initiative - Led the strategic migration from legacy Laravel Blade templates to Vue.js, resulting in significant improvements to performance, responsiveness, and delivery speed.}
            \item {Testing Framework Implementation - Established a robust testing framework using Jest and Vue Test Utils with comprehensive unit and integration test coverage, driving high code quality and reliability.}
            \item {Mentorship \& Code Quality - Mentored other developers on frontend best practices, code quality standards, and modern development workflows.}
        \end{cvsubitems}
        \begin{cvitems} % Description(s) of tasks/responsibilities
            \item {Backend Development - Expanded technical scope into full-stack development, taking ownership of critical backend systems and infrastructure initiatives.}
        \end{cvitems}
        \begin{cvsubitems}
            \item {Laravel API \& Infrastructure - Designed and implemented new backend features and architected standardized backend patterns including service layers, repository patterns, and query optimization strategies.}
            \item {Monolith Architecture Modernization - Rearchitected the ReviewPush monolith from a controller-transformer pattern to a Controller-Service-Transformer model.}
            \item {Testing Framework Overhaul - Implemented a comprehensive testing strategy that transformed the backend from sporadic, ad-hoc tests to a robust suite of unit and integration tests, improving release.}
            \item {FastPDF - Architected and deployed a Fastify microservice for generating production-grade PDF reports from complex HTML, CSS, and JavaScript pages, with comprehensive logging, health monitoring, OpenTelemetry-based observability, JWT.}
        \end{cvsubitems}
        \begin{cvitems}
            \item {Leadership - Owned architecture decisions, mentored engineers, and drove business-wide priorities with a focus on performance, reliability, and software quality.}
        \end{cvitems}
    }
\end{cventries}

